EMBEDDED_FILES = {
  "build_exe.py": "# -*- coding: utf-8 -*-\n\"\"\"Сборщик портативной версии «Конвертер АМИРС» со встроенным PaddleOCR.\n\nЧто делает (6 шагов): проверка Python → PyInstaller → зависимости → портативные модели\nPaddleOCR → сборка по .spec → портативная папка, ярлык и проверка запуска.\n\nПараметры командной строки:\n  --dry-run   только проверить окружение и тесты, ничего не устанавливать и не собирать\n  --no-pause  не ждать нажатия Enter в конце (для автоматического запуска)\nПеременные окружения:\n  AMIRS_SKIP_TESTS=1    не запускать автотесты перед сборкой\n  AMIRS_DEST_DIR=...    куда положить готовую портативную папку (по умолчанию — Рабочий стол)\n  AMIRS_CONSOLE=1       отладочная сборка с окном консоли\n  AMIRS_EMBED_MODELS=1  дополнительно вшить модели внутрь сборки (см. .spec)\n  AMIRS_NO_PAUSE=1      то же, что --no-pause\n\nВерсии пакетов: если рядом лежит requirements-build.txt со строками «пакет==версия»,\nставятся именно они; фактические версии каждой сборки пишутся в build_versions.txt.\n\"\"\"\nimport os\nimport re\nimport shutil\nimport subprocess\nimport sys\nimport tempfile\n\nAPP_FILE = \"amirs_converter.py\"\nAPP_EXE_NAME = \"Конвертер_АМИРС\"\nCORE_PACKAGES = [\"pypdf\", \"pypdfium2\", \"Pillow\"]\nOCR_PACKAGES = [\"paddlepaddle\", \"paddleocr\"]\nUSER_FILES = (\"amirs_settings.json\", \"amirs_docs.json\", \"amirs_fees.json\")  # правятся пользователем\nSHIPPED_FILES = (\"amirs_docs.json\", \"amirs_fees.json\", \"Инструкция_PaddleOCR.txt\", \"Пример_пакета_АМИРС.xml\")\nTEST_MODULES = (\"test_amirs_regression\", \"test_amirs_converter\")\n\n\n# ----------------------------------------------------------------- вспомогательное\ndef set_color(code: str) -> None:\n    if os.name == \"nt\":\n        os.system(f\"color {code}\")\n\n\ndef read_app_version(app_path: str) -> str:\n    \"\"\"Версия берётся из самой программы (APP_VERSION), а не пишется в сборщике вручную.\"\"\"\n    try:\n        with open(app_path, encoding=\"utf-8\") as fh:\n            m = re.search(r'^APP_VERSION\\s*=\\s*[\"\\']([^\"\\']+)[\"\\']', fh.read(), re.M)\n        return m.group(1) if m else \"?\"\n    except OSError:\n        return \"?\"\n\n\ndef ps_quote(value: str) -> str:\n    \"\"\"Экранирование строки для одинарных кавычек PowerShell (апостроф удваивается).\"\"\"\n    return value.replace(\"'\", \"''\")\n\n\ndef read_requirements(path: str):\n    \"\"\"Строки с пакетами из requirements-файла (без комментариев и пустых).\"\"\"\n    try:\n        with open(path, encoding=\"utf-8\") as fh:\n            return [ln.strip() for ln in fh if ln.strip() and not ln.strip().startswith(\"#\")]\n    except OSError:\n        return []\n\n\ndef pause_if_interactive(force_no_pause: bool = False) -> None:\n    if force_no_pause or os.environ.get(\"AMIRS_NO_PAUSE\") == \"1\":\n        return\n    try:\n        if sys.stdin is None or not sys.stdin.isatty():\n            return\n        input(\"Нажмите Enter для выхода...\")\n    except (EOFError, OSError):\n        pass\n\n\ndef ensure_compatible_python() -> None:\n    \"\"\"Если скрипт запущен на Python 3.14+, перезапускает его через 3.12/3.11/3.10/3.13.\"\"\"\n    if sys.version_info < (3, 14) or os.environ.get(\"AMIRS_PY_SWITCHED\") == \"1\":\n        return\n    if os.name == \"nt\" and shutil.which(\"py\"):\n        for ver in (\"-3.12\", \"-3.11\", \"-3.10\", \"-3.13\"):\n            chk = subprocess.run([\"py\", ver, \"-c\", \"import sys; print(sys.executable)\"],\n                                 capture_output=True, text=True)\n            if chk.returncode == 0 and chk.stdout.strip():\n                alt_py = chk.stdout.strip().splitlines()[-1]\n                print(f\"[АВТОВЫБОР] Python {sys.version.split()[0]} не поддерживает бинарные пакеты Paddle.\")\n                print(f\"            Переключаюсь на совместимый Python ({ver}): {alt_py}\\n\")\n                env = os.environ.copy()\n                env[\"AMIRS_PY_SWITCHED\"] = \"1\"\n                res = subprocess.run([alt_py, \"-X\", \"utf8\", os.path.abspath(__file__)] + sys.argv[1:], env=env)\n                sys.exit(res.returncode)\n\n\ndef run_tests_gate(py_exe: str, base_dir: str):\n    \"\"\"Автотесты перед сборкой: сломанная версия не должна превращаться в EXE.\n    Возвращает (True/False/None, вывод); None — тестов рядом нет или они отключены.\"\"\"\n    if os.environ.get(\"AMIRS_SKIP_TESTS\") == \"1\":\n        return None, \"пропущено (AMIRS_SKIP_TESTS=1)\"\n    mods = [m for m in TEST_MODULES if os.path.isfile(os.path.join(base_dir, m + \".py\"))]\n    if not mods:\n        return None, \"файлов тестов рядом нет\"\n    sandbox = tempfile.mkdtemp(prefix=\"amirs_build_tests_\")  # тесты не должны трогать профиль пользователя\n    env = os.environ.copy()\n    env.update(LOCALAPPDATA=sandbox, APPDATA=sandbox, HOME=sandbox, USERPROFILE=sandbox)\n    try:\n        res = subprocess.run([py_exe, \"-X\", \"utf8\", \"-m\", \"unittest\", *mods], cwd=base_dir, env=env,\n                             capture_output=True, text=True, encoding=\"utf-8\", errors=\"replace\", timeout=900)\n    except subprocess.TimeoutExpired:\n        return False, \"тесты не завершились за 15 минут\"\n    finally:\n        shutil.rmtree(sandbox, ignore_errors=True)\n    tail = \"\\n\".join((res.stdout + res.stderr).strip().splitlines()[-6:])\n    return res.returncode == 0, tail\n\n\ndef pip_install(py_exe: str, args) -> bool:\n    return subprocess.run([py_exe, \"-m\", \"pip\", \"install\", \"--disable-pip-version-check\", *args]).returncode == 0\n\n\ndef record_versions(py_exe: str, base_dir: str) -> str:\n    \"\"\"Записывает фактические версии ключевых пакетов в build_versions.txt (для закрепления).\"\"\"\n    wanted = {\"pyinstaller\", \"paddlepaddle\", \"paddleocr\", \"pypdf\", \"pypdfium2\", \"pillow\"}\n    res = subprocess.run([py_exe, \"-m\", \"pip\", \"freeze\"], capture_output=True, text=True)\n    lines = [ln for ln in res.stdout.splitlines() if ln.split(\"==\")[0].strip().lower() in wanted]\n    path = os.path.join(base_dir, \"build_versions.txt\")\n    if lines:\n        with open(path, \"w\", encoding=\"utf-8\") as fh:\n            fh.write(f\"# Python {sys.version.split()[0]}; перенесите нужные строки в requirements-build.txt\\n\")\n            fh.write(\"\\n\".join(sorted(lines, key=str.lower)) + \"\\n\")\n    return path if lines else \"\"\n\n\ndef ensure_portable_paddle_models(py_exe: str, base_dir: str) -> str:\n    \"\"\"Готовит портативную папку paddle_models (det/rec/cls и кэш) для работы без интернета.\"\"\"\n    portable_models = os.path.join(base_dir, \"paddle_models\")\n    os.makedirs(portable_models, exist_ok=True)\n    prep_code = (\n        \"import os\\n\"\n        \"os.environ['PADDLE_PDX_DISABLE_MODEL_SOURCE_CHECK'] = 'True'\\n\"\n        \"from paddleocr import PaddleOCR\\n\"\n        \"ocr = PaddleOCR(lang='ru')\\n\"\n        \"home = os.path.expanduser('~')\\n\"\n        \"for sub in ('.paddleocr', '.paddlex'):\\n\"\n        \"    p = os.path.join(home, sub)\\n\"\n        \"    if os.path.isdir(p):\\n\"\n        \"        print('CACHE_DIR=' + p)\\n\"\n    )\n    try:\n        res = subprocess.run([py_exe, \"-c\", prep_code], capture_output=True, text=True,\n                             encoding=\"utf-8\", errors=\"replace\", timeout=1800)\n    except subprocess.TimeoutExpired:\n        print(\" [ВНИМАНИЕ] Загрузка моделей не завершилась за 30 минут.\")\n        return \"\"\n    if res.returncode != 0:\n        print(\" [ВНИМАНИЕ] Модели PaddleOCR не подготовлены: \"\n              + (res.stderr.strip().splitlines() or [\"причина неизвестна\"])[-1])\n        return portable_models if os.listdir(portable_models) else \"\"\n    for line in res.stdout.splitlines():\n        if line.startswith(\"CACHE_DIR=\"):\n            src_cache = line.split(\"CACHE_DIR=\", 1)[1].strip()\n            dst_cache = os.path.join(portable_models, os.path.basename(src_cache))\n            if os.path.isdir(src_cache) and not os.path.exists(dst_cache):\n                try:\n                    shutil.copytree(src_cache, dst_cache)\n                except OSError as exc:\n                    print(f\" [ВНИМАНИЕ] Кэш {src_cache} не скопирован: {exc}\")\n    # Раскладываем det / rec / cls в корень. Обход — по ЗАРАНЕЕ собранному списку,\n    # иначе os.walk заходит в только что созданные копии.\n    for cur_root, _dirs, files in list(os.walk(portable_models)):\n        if not any(f.endswith((\".pdmodel\", \".pdiparams\", \".json\", \".yml\")) for f in files):\n            continue\n        low = cur_root.replace(\"\\\\\", \"/\").lower()\n        for role in (\"det\", \"rec\", \"cls\"):\n            target = os.path.join(portable_models, role)\n            if os.path.abspath(cur_root) == os.path.abspath(target) or os.path.exists(target):\n                continue\n            if f\"/{role}/\" in low or low.endswith(f\"/{role}\") or role in os.path.basename(cur_root).lower():\n                try:\n                    shutil.copytree(cur_root, target)\n                except OSError as exc:\n                    print(f\" [ВНИМАНИЕ] Папка {cur_root} не скопирована как {role}: {exc}\")\n    if os.path.isdir(os.path.join(portable_models, \"det\")) and os.path.isdir(os.path.join(portable_models, \"rec\")):\n        for r_dir, _d, f_list in os.walk(portable_models):\n            for fn in f_list:\n                if fn.endswith(\".tar\"):\n                    try:\n                        os.remove(os.path.join(r_dir, fn))\n                    except OSError:\n                        pass\n    return portable_models if os.listdir(portable_models) else \"\"\n\n\ndef create_windows_shortcut(target_exe: str, shortcut_path: str, work_dir: str) -> bool:\n    \"\"\"Создаёт ярлык .lnk (Windows). Пути экранируются: апостроф в имени профиля не ломает команду.\"\"\"\n    if os.name != \"nt\":\n        return False\n    ps_cmd = (\"$ws = New-Object -ComObject WScript.Shell; \"\n              f\"$s = $ws.CreateShortcut('{ps_quote(shortcut_path)}'); \"\n              f\"$s.TargetPath = '{ps_quote(target_exe)}'; \"\n              f\"$s.WorkingDirectory = '{ps_quote(work_dir)}'; \"\n              \"$s.Save()\")\n    try:\n        res = subprocess.run([\"powershell\", \"-NoProfile\", \"-ExecutionPolicy\", \"Bypass\", \"-Command\", ps_cmd],\n                             stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)\n        return res.returncode == 0 and os.path.isfile(shortcut_path)\n    except OSError:\n        return False\n\n\ndef preserve_user_files(folder: str, names=USER_FILES) -> dict:\n    \"\"\"Перед пересборкой запоминает правленные пользователем файлы настроек и справочников.\"\"\"\n    kept = {}\n    for name in names:\n        p = os.path.join(folder, name)\n        if os.path.isfile(p):\n            with open(p, \"rb\") as fh:\n                kept[name] = fh.read()\n    return kept\n\n\ndef restore_user_files(folder: str, kept: dict) -> None:\n    for name, data in kept.items():\n        with open(os.path.join(folder, name), \"wb\") as fh:\n            fh.write(data)\n\n\ndef smoke_test_exe(exe_path: str) -> bool:\n    \"\"\"Запускает собранный EXE в режиме командной строки и проверяет код возврата.\"\"\"\n    env = os.environ.copy()\n    env[\"PADDLE_PDX_DISABLE_MODEL_SOURCE_CHECK\"] = \"True\"\n    try:\n        res = subprocess.run([exe_path, \"--list-sections\"], env=env, capture_output=True, timeout=180)\n    except (subprocess.TimeoutExpired, OSError) as exc:\n        print(f\" [ПРОВЕРКА] EXE не запустился: {exc}\")\n        return False\n    if res.returncode != 0:\n        print(f\" [ПРОВЕРКА] EXE вернул код {res.returncode}\")\n    return res.returncode == 0\n\n\ndef find_desktop(base_dir: str) -> str:\n    override = os.environ.get(\"AMIRS_DEST_DIR\")\n    if override:\n        os.makedirs(override, exist_ok=True)\n        return override\n    user_profile = os.environ.get(\"USERPROFILE\", os.path.expanduser(\"~\"))\n    for c in (os.path.join(user_profile, \"Desktop\"), os.path.join(user_profile, \"OneDrive\", \"Desktop\"),\n              os.path.join(user_profile, \"Рабочий стол\"), base_dir):\n        if os.path.isdir(c):\n            return c\n    return base_dir\n\n\n# ----------------------------------------------------------------- основной сценарий\ndef main(argv=None) -> int:\n    argv = list(sys.argv[1:] if argv is None else argv)\n    dry_run = \"--dry-run\" in argv\n    ensure_compatible_python()\n    base_dir = os.path.dirname(os.path.abspath(__file__))\n    os.chdir(base_dir)\n    version = read_app_version(os.path.join(base_dir, APP_FILE))\n    if os.name == \"nt\":\n        os.system(f\"title Сборка Конвертера АМИРС v{version} (PaddleOCR)\")\n    set_color(\"1F\")\n    print(\"=\" * 65)\n    print(f\" СБОРКА ПОРТАТИВНОЙ ВЕРСИИ КОНВЕРТЕРА АМИРС v{version}\")\n    print(\" Распознавание сканов PDF, DOCX, JPG, PNG, TIFF, WEBP, BMP (PaddleOCR)\")\n    print(\"=\" * 65 + \"\\n\")\n\n    if not os.path.isfile(os.path.join(base_dir, APP_FILE)):\n        set_color(\"4F\")\n        print(f\"[ОШИБКА] Рядом с этим файлом нет файла {APP_FILE}.\")\n        print(\"Распакуйте все файлы архива в одну папку и запустите сборку снова.\")\n        return 1\n    py_exe = sys.executable\n    print(f\"[1/6] Python: {sys.version.split()[0]} ({py_exe}); версия программы: {version}\\n\")\n\n    ok, tail = run_tests_gate(py_exe, base_dir)\n    if ok is None:\n        print(f\" Автотесты: {tail}\\n\")\n    elif ok:\n        print(\" Автотесты пройдены.\\n\")\n    else:\n        set_color(\"4F\")\n        print(\"[ОШИБКА] Автотесты не пройдены — сборка остановлена (чтобы не выпустить неисправный EXE).\")\n        print(tail)\n        print(\"Исправьте причину или, осознанно, запустите с AMIRS_SKIP_TESTS=1.\")\n        return 1\n    if dry_run:\n        print(\"[DRY-RUN] Проверка окружения завершена; установка и сборка не выполнялись.\")\n        return 0\n\n    print(\"[2/6] Проверяем PyInstaller...\")\n    reqs_file = os.path.join(base_dir, \"requirements-build.txt\")\n    pinned = read_requirements(reqs_file)\n    if subprocess.run([py_exe, \"-m\", \"PyInstaller\", \"--version\"], capture_output=True).returncode != 0:\n        print(\" Устанавливаю PyInstaller (нужен интернет)...\")\n        if not pip_install(py_exe, [x for x in pinned if x.lower().startswith(\"pyinstaller\")]\n                           or [\"--upgrade\", \"pyinstaller\"]):\n            set_color(\"4F\")\n            print(\"[ОШИБКА] Не удалось установить PyInstaller.\")\n            return 1\n    print(\" PyInstaller готов.\\n\")\n\n    print(\"[3/6] Устанавливаем PDF-модули, Pillow и PaddleOCR...\")\n    core_ok = True\n    if pinned:\n        print(f\" Используются закреплённые версии из {os.path.basename(reqs_file)} ({len(pinned)} шт.).\")\n        core_ok = pip_install(py_exe, [\"-r\", reqs_file])\n    else:\n        print(\" Версии не закреплены — будут установлены последние (см. build_versions.txt после сборки).\")\n    core_ok = core_ok and pip_install(py_exe, CORE_PACKAGES)  # уже установленные pip пропускает\n    if core_ok and not pip_install(py_exe, OCR_PACKAGES):\n        print(\" [ВНИМАНИЕ] PaddleOCR не установлен: сканы будут получать статус «проверить визуально».\")\n    if not core_ok:\n        set_color(\"4F\")\n        print(\"[ОШИБКА] Не установлены обязательные модули (pypdf, pypdfium2, Pillow).\")\n        return 1\n    print(\" Модули готовы.\\n\")\n\n    print(\"[4/6] Портативные модели PaddleOCR (rus)...\")\n    portable_models = ensure_portable_paddle_models(py_exe, base_dir)\n    if portable_models:\n        print(f\" Модели готовы: {portable_models}\\n\")\n    else:\n        print(\" [ИНФО] Моделей нет: они загрузятся при первом распознавании (нужен интернет).\\n\")\n\n    print(\"[5/6] Сборка по профилю Конвертер_АМИРС.spec...\")\n    spec_file = os.path.join(base_dir, f\"{APP_EXE_NAME}.spec\")\n    if os.path.isfile(spec_file):\n        cmd = [py_exe, \"-m\", \"PyInstaller\", \"--noconfirm\", \"--clean\", spec_file]\n    else:\n        cmd = [py_exe, \"-m\", \"PyInstaller\", \"--noconfirm\", \"--clean\", \"--onedir\", \"--windowed\",\n               \"--name\", APP_EXE_NAME, \"--hidden-import\", \"pypdf\", \"--hidden-import\", \"pypdfium2\",\n               \"--hidden-import\", \"PIL\", \"--noupx\"]\n        for pkg in (\"pypdfium2\", \"pypdfium2_raw\", \"paddleocr\", \"paddle\", \"pyclipper\", \"shapely\",\n                    \"skimage\", \"imgaug\", \"lmdb\"):\n            if subprocess.run([py_exe, \"-c\", f\"import {pkg}\"], stdout=subprocess.DEVNULL,\n                              stderr=subprocess.DEVNULL).returncode == 0:\n                cmd += [\"--collect-all\", pkg]\n        cmd.append(APP_FILE)\n    if subprocess.run(cmd).returncode != 0:\n        set_color(\"4F\")\n        print(\"\\n[ОШИБКА] Сборка не удалась.\")\n        return 1\n    versions_path = record_versions(py_exe, base_dir)\n    print(\"\")\n\n    print(\"[6/6] Портативная папка, ярлык, проверка запуска...\")\n    built_folder = os.path.join(base_dir, \"dist\", APP_EXE_NAME)\n    built_exe = os.path.join(built_folder, APP_EXE_NAME + \".exe\")\n    if not os.path.isfile(built_exe):\n        built_exe = os.path.join(base_dir, \"dist\", APP_EXE_NAME + \".exe\")\n        built_folder = \"\"\n    if not os.path.isfile(built_exe):\n        set_color(\"4F\")\n        print(f\"[ОШИБКА] Не найден собранный {APP_EXE_NAME}.exe в папке dist.\")\n        return 1\n\n    dest_dir = find_desktop(base_dir)\n    bundle = os.path.join(dest_dir, APP_EXE_NAME + \"_Portable\")\n    kept = preserve_user_files(bundle)  # правки пользователя переживают пересборку\n    if os.path.exists(bundle):\n        shutil.rmtree(bundle, ignore_errors=True)\n    if built_folder and os.path.isdir(built_folder):\n        shutil.copytree(built_folder, bundle)\n    else:\n        os.makedirs(bundle, exist_ok=True)\n        shutil.copy2(built_exe, os.path.join(bundle, APP_EXE_NAME + \".exe\"))\n    for name in SHIPPED_FILES:  # справочники и инструкции; настройки (суд, судья) НЕ поставляются\n        src = os.path.join(base_dir, name)\n        if os.path.isfile(src):\n            shutil.copy2(src, os.path.join(bundle, name))\n    restore_user_files(bundle, kept)\n    if kept:\n        print(\" Сохранены ваши файлы: \" + \", \".join(sorted(kept)))\n    if portable_models and os.path.isdir(portable_models):\n        dst_models = os.path.join(bundle, \"paddle_models\")\n        shutil.rmtree(dst_models, ignore_errors=True)\n        shutil.copytree(portable_models, dst_models)\n\n    portable_exe = os.path.join(bundle, APP_EXE_NAME + \".exe\")\n    shortcut = os.path.join(dest_dir, \"Конвертер АМИРС.lnk\")\n    shortcut_ok = create_windows_shortcut(portable_exe, shortcut, bundle)\n    smoke_ok = smoke_test_exe(portable_exe) if os.name == \"nt\" else None\n\n    set_color(\"2F\" if smoke_ok is not False else \"6F\")\n    print(\"=\" * 65)\n    print(\" ПОРТАТИВНАЯ ВЕРСИЯ ГОТОВА\" if smoke_ok is not False\n          else \" СОБРАНО, НО ПРОВЕРКА ЗАПУСКА НЕ ПРОЙДЕНА — проверьте вручную\")\n    print(\"=\" * 65 + \"\\n\")\n    if shortcut_ok:\n        print(f\"1) Ярлык: {shortcut}\")\n    print(f\"2) Портативная папка (для ПК и флешки): {bundle}\")\n    print(f\"3) Исполняемый файл: {portable_exe}\")\n    if versions_path:\n        print(f\"4) Версии пакетов этой сборки: {versions_path}\")\n    print(\"\\nНастройки суда и судьи в сборку не входят — задайте их при первом запуске.\")\n    return 0 if smoke_ok is not False else 2\n\n\nif __name__ == \"__main__\":\n    try:\n        code = main()\n    except Exception as exc:  # noqa: BLE001 — сборщик должен показать причину, а не закрыть окно\n        set_color(\"4F\")\n        print(f\"[КРИТИЧЕСКАЯ ОШИБКА] {type(exc).__name__}: {exc}\")\n        code = 1\n    print(\"\")\n    pause_if_interactive(\"--no-pause\" in sys.argv)\n    sys.exit(code)\n",
  "test_build_files.py": "# -*- coding: utf-8 -*-\n\"\"\"Проверки файлов сборки: build_exe.py, Собрать_EXE.bat, Конвертер_АМИРС.spec.\nЗапуск: python -m unittest test_build_files -v\n(Реальная сборка и запуск .bat требуют Windows; здесь проверяются логика и статические правила.)\"\"\"\nimport os\nimport re\nimport shutil\nimport subprocess\nimport sys\nimport tempfile\nimport unittest\n\nimport build_exe as be\n\nHERE = os.path.dirname(os.path.abspath(__file__))\nBAT = os.path.join(HERE, \"Собрать_EXE.bat\")\nSPEC = os.path.join(HERE, \"Конвертер_АМИРС.spec\")\n\n\ndef _read(p):\n    with open(p, encoding=\"utf-8\") as fh:\n        return fh.read()\n\n\nclass BatFile(unittest.TestCase):\n    def test_errorlevel_never_percent_expanded_inside_blocks(self):\n        \"\"\"Классическая ловушка cmd: %errorlevel% внутри ( ... ) раскрывается до выполнения команд.\"\"\"\n        depth = 0\n        for n, line in enumerate(_read(BAT).splitlines(), 1):\n            code = line.strip()\n            if code.lower().startswith(\"rem \"):\n                continue\n            if depth > 0:\n                self.assertNotIn(\"%errorlevel%\", code.lower(), f\"строка {n}: {line}\")\n            depth += code.count(\"(\") - code.count(\")\")\n            self.assertGreaterEqual(depth, 0, f\"строка {n}: лишняя ')'\")\n        self.assertEqual(depth, 0, \"несбалансированные скобки\")\n\n    def test_exit_code_is_propagated_and_all_gotos_have_labels(self):\n        text = _read(BAT)\n        self.assertRegex(text, r\"(?im)^:DONE\\s*\\r?\\n\\s*exit /b %errorlevel%\")\n        labels = set(re.findall(r\"(?m)^:(\\w+)\", text))\n        for target in re.findall(r\"(?i)goto\\s+(\\w+)\", text):\n            self.assertIn(target, labels)\n\n    def test_ascii_only_and_crlf(self):\n        with open(BAT, \"rb\") as fh:\n            raw = fh.read()\n        self.assertTrue(all(b < 128 for b in raw), \"в .bat остался не-ASCII текст\")\n        self.assertIn(b\"\\r\\n\", raw)\n        self.assertNotIn(b\"\\n\", raw.replace(b\"\\r\\n\", b\"\"))\n\n    def test_passes_arguments_to_builder(self):\n        self.assertGreaterEqual(_read(BAT).count(\"build_exe.py %*\"), 3)\n\n\nclass SpecFile(unittest.TestCase):\n    def test_spec_compiles_and_has_safe_defaults(self):\n        text = _read(SPEC)\n        compile(text, SPEC, \"exec\")  # синтаксис\n        self.assertNotIn(\"upx=True\", text)\n        self.assertEqual(text.count(\"upx=False\"), 2)\n        self.assertIn(\"AMIRS_CONSOLE\", text)  # отладочная сборка с консолью\n        self.assertNotRegex(text, r\"except Exception:\\s*\\n\\s*pass\")  # пропуск пакета не должен быть немым\n\n\nclass Builder(unittest.TestCase):\n    def test_version_is_read_from_app_not_hardcoded(self):\n        self.assertNotRegex(_read(os.path.join(HERE, \"build_exe.py\")), r\"v3\\.7\")\n        app = os.path.join(HERE, \"amirs_converter.py\")\n        if os.path.isfile(app):\n            self.assertRegex(be.read_app_version(app), r\"^\\d+\\.\\d+\\.\\d+$\")\n        self.assertEqual(be.read_app_version(\"/нет/такого/файла.py\"), \"?\")\n\n    def test_powershell_quote_escapes_apostrophe(self):\n        self.assertEqual(be.ps_quote(\"C:\\\\Users\\\\O'Brien\\\\a.lnk\"), \"C:\\\\Users\\\\O''Brien\\\\a.lnk\")\n\n    def test_requirements_parser_ignores_comments(self):\n        d = tempfile.mkdtemp()\n        self.addCleanup(shutil.rmtree, d, True)\n        p = os.path.join(d, \"r.txt\")\n        with open(p, \"w\", encoding=\"utf-8\") as fh:\n            fh.write(\"# комментарий\\n\\npaddleocr==2.7.3\\n pypdf==5.9.0 \\n# pillow==1\\n\")\n        self.assertEqual(be.read_requirements(p), [\"paddleocr==2.7.3\", \"pypdf==5.9.0\"])\n        self.assertEqual(be.read_requirements(os.path.join(d, \"нет.txt\")), [])\n        shipped = os.path.join(HERE, \"requirements-build.txt\")\n        if os.path.isfile(shipped):\n            self.assertEqual(be.read_requirements(shipped), [])  # шаблон поставляется без пинов\n\n    def test_user_files_survive_rebuild(self):\n        d = tempfile.mkdtemp()\n        self.addCleanup(shutil.rmtree, d, True)\n        with open(os.path.join(d, \"amirs_settings.json\"), \"w\", encoding=\"utf-8\") as fh:\n            fh.write('{\"judge\": \"Мой судья\"}')\n        with open(os.path.join(d, \"amirs_fees.json\"), \"wb\") as fh:\n            fh.write(b'{\"x\": 1}')\n        kept = be.preserve_user_files(d)\n        self.assertEqual(sorted(kept), [\"amirs_fees.json\", \"amirs_settings.json\"])\n        shutil.rmtree(d)\n        os.makedirs(d)\n        with open(os.path.join(d, \"amirs_fees.json\"), \"wb\") as fh:\n            fh.write(b'{\"shipped\": true}')\n        be.restore_user_files(d, kept)\n        with open(os.path.join(d, \"amirs_fees.json\"), \"rb\") as fh:\n            self.assertEqual(fh.read(), b'{\"x\": 1}')\n        self.assertIn(\"Мой судья\", _read(os.path.join(d, \"amirs_settings.json\")))\n\n    def test_settings_with_judge_are_not_shipped(self):\n        self.assertNotIn(\"amirs_settings.json\", be.SHIPPED_FILES)\n\n    def test_pause_does_not_crash_without_stdin(self):\n        old = sys.stdin\n        try:\n            sys.stdin = None\n            be.pause_if_interactive()\n            be.pause_if_interactive(True)\n        finally:\n            sys.stdin = old\n\n    def test_dry_run_in_clean_folder_runs_tests_gate(self):\n        \"\"\"Копирует комплект во временную папку и запускает сборщик в режиме --dry-run.\"\"\"\n        need = (\"build_exe.py\", \"amirs_converter.py\", \"test_amirs_regression.py\", \"test_amirs_converter.py\")\n        if not all(os.path.isfile(os.path.join(HERE, f)) for f in need):\n            self.skipTest(\"рядом нет amirs_converter.py и тестов\")\n        d = tempfile.mkdtemp()\n        self.addCleanup(shutil.rmtree, d, True)\n        for f in need:\n            shutil.copy2(os.path.join(HERE, f), d)\n        env = dict(os.environ, AMIRS_NO_PAUSE=\"1\")\n        if env.get(\"PYTHONPATH\"):  # относительные пути (если заданы) делаем абсолютными\n            env[\"PYTHONPATH\"] = os.pathsep.join(os.path.abspath(os.path.join(HERE, p))\n                                                for p in env[\"PYTHONPATH\"].split(os.pathsep))\n        res = subprocess.run([sys.executable, \"-X\", \"utf8\", \"build_exe.py\", \"--dry-run\", \"--no-pause\"],\n                             cwd=d, env=env, capture_output=True, text=True, encoding=\"utf-8\", timeout=900)\n        self.assertEqual(res.returncode, 0, res.stdout + res.stderr)\n        self.assertIn(\"Автотесты пройдены\", res.stdout)\n        self.assertIn(\"DRY-RUN\", res.stdout)\n\n    def test_failed_tests_block_the_build(self):\n        d = tempfile.mkdtemp()\n        self.addCleanup(shutil.rmtree, d, True)\n        shutil.copy2(os.path.join(HERE, \"build_exe.py\"), d)\n        with open(os.path.join(d, \"amirs_converter.py\"), \"w\", encoding=\"utf-8\") as fh:\n            fh.write('APP_VERSION = \"9.9.9\"\\n')\n        with open(os.path.join(d, \"test_amirs_converter.py\"), \"w\", encoding=\"utf-8\") as fh:\n            fh.write(\"import unittest\\nclass T(unittest.TestCase):\\n    def test_x(self):\\n        self.assertTrue(False)\\n\")\n        res = subprocess.run([sys.executable, \"-X\", \"utf8\", \"build_exe.py\", \"--dry-run\", \"--no-pause\"],\n                             cwd=d, capture_output=True, text=True, encoding=\"utf-8\", timeout=300)\n        self.assertEqual(res.returncode, 1)\n        self.assertIn(\"сборка остановлена\", res.stdout)\n\n\nif __name__ == \"__main__\":\n    unittest.main(verbosity=2)\n",
  "test_amirs_converter.py": "# -*- coding: utf-8 -*-\n\"\"\"Модульные и интеграционные тесты для amirs_converter.py (версии 3.8.0–3.8.2).\"\"\"\n\nimport os\nimport tempfile\nimport unittest\nimport xml.etree.ElementTree as ET\nimport zipfile\n\nimport amirs_converter as ac\n\n\ndef _build_test_xlsx(path: str, headers: list, data_rows: list) -> str:\n    \"\"\"Создаёт минимальную валидную книгу .xlsx без сторонних библиотек.\"\"\"\n    rows = [[(ac._S_HEAD, h) for h in headers]]\n    for r in data_rows:\n        rows.append([(ac._S_DATA, str(v) if v is not None else \"\") for v in r])\n    sheet_xml = ac._tpl_worksheet(rows, col_widths=[22] * len(headers), freeze_rows=1)\n\n    content_types = (\n        '<?xml version=\"1.0\" encoding=\"UTF-8\" standalone=\"yes\"?>'\n        '<Types xmlns=\"http://schemas.openxmlformats.org/package/2006/content-types\">'\n        '<Default Extension=\"rels\" ContentType=\"application/vnd.openxmlformats-package.relationships+xml\"/>'\n        '<Default Extension=\"xml\" ContentType=\"application/xml\"/>'\n        '<Override PartName=\"/xl/workbook.xml\" '\n        'ContentType=\"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml\"/>'\n        '<Override PartName=\"/xl/worksheets/sheet1.xml\" '\n        'ContentType=\"application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml\"/>'\n        '<Override PartName=\"/xl/styles.xml\" '\n        'ContentType=\"application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml\"/>'\n        '</Types>'\n    ).encode(\"utf-8\")\n    rels = (\n        '<?xml version=\"1.0\" encoding=\"UTF-8\" standalone=\"yes\"?>'\n        '<Relationships xmlns=\"http://schemas.openxmlformats.org/package/2006/relationships\">'\n        '<Relationship Id=\"rId1\" '\n        'Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument\" '\n        'Target=\"xl/workbook.xml\"/>'\n        '</Relationships>'\n    ).encode(\"utf-8\")\n    wb = (\n        '<?xml version=\"1.0\" encoding=\"UTF-8\" standalone=\"yes\"?>'\n        f'<workbook xmlns=\"{ac.NS[1:-1]}\" xmlns:r=\"{ac.NS_R[1:-1]}\">'\n        '<sheets><sheet name=\"Реестр\" sheetId=\"1\" r:id=\"rId1\"/></sheets>'\n        '</workbook>'\n    ).encode(\"utf-8\")\n    wb_rels = (\n        '<?xml version=\"1.0\" encoding=\"UTF-8\" standalone=\"yes\"?>'\n        '<Relationships xmlns=\"http://schemas.openxmlformats.org/package/2006/relationships\">'\n        '<Relationship Id=\"rId1\" '\n        'Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet\" '\n        'Target=\"worksheets/sheet1.xml\"/>'\n        '<Relationship Id=\"rId2\" '\n        'Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles\" '\n        'Target=\"styles.xml\"/>'\n        '</Relationships>'\n    ).encode(\"utf-8\")\n\n    with zipfile.ZipFile(path, \"w\", zipfile.ZIP_DEFLATED) as z:\n        z.writestr(\"[Content_Types].xml\", content_types)\n        z.writestr(\"_rels/.rels\", rels)\n        z.writestr(\"xl/workbook.xml\", wb)\n        z.writestr(\"xl/_rels/workbook.xml.rels\", wb_rels)\n        z.writestr(\"xl/styles.xml\", ac._TPL_STYLES.encode(\"utf-8\"))\n        z.writestr(\"xl/worksheets/sheet1.xml\", sheet_xml)\n    return path\n\n\ndef _read_docx_text(docx_path: str) -> str:\n    \"\"\"Извлекает весь текст из .docx.\"\"\"\n    with zipfile.ZipFile(docx_path, \"r\") as z:\n        root = ET.fromstring(z.read(\"word/document.xml\"))\n    ns = \"{http://schemas.openxmlformats.org/wordprocessingml/2006/main}\"\n    paragraphs = []\n    for p in root.iter(ns + \"p\"):\n        txt = \"\".join(t.text or \"\" for t in p.iter(ns + \"t\"))\n        if txt:\n            paragraphs.append(txt)\n    return \"\\n\".join(paragraphs)\n\n\nclass TestParseAmount(unittest.TestCase):\n    \"\"\"Тесты разбора денежных сумм в различных форматах и порогов правдоподобия.\"\"\"\n\n    def test_russian_formats(self):\n        self.assertEqual(ac.parse_amount(\"1 234,56\"), \"1234.56\")\n        self.assertEqual(ac.parse_amount(\"1\\u00A0234,56\"), \"1234.56\")\n        self.assertEqual(ac.parse_amount(\"1234,56\"), \"1234.56\")\n        self.assertEqual(ac.parse_amount(\"0,50\"), \"0.50\")\n        self.assertEqual(ac.parse_amount(\"1 234 567,89\"), \"1234567.89\")\n\n    def test_american_and_mixed_formats(self):\n        self.assertEqual(ac.parse_amount(\"1,234.56\"), \"1234.56\")\n        self.assertEqual(ac.parse_amount(\"12,345.67\"), \"12345.67\")\n        self.assertEqual(ac.parse_amount(\"1,234,567.89\"), \"1234567.89\")\n        self.assertEqual(ac.parse_amount(\"1.234,56\"), \"1234.56\")\n        self.assertEqual(ac.parse_amount(\"1.234.567,89\"), \"1234567.89\")\n\n    def test_currency_suffixes_and_scientific(self):\n        self.assertEqual(ac.parse_amount(\"1 234,56 руб\"), \"1234.56\")\n        self.assertEqual(ac.parse_amount(\"3 500,50 руб.\"), \"3500.50\")\n        self.assertEqual(ac.parse_amount(\"12,345.67 р.\"), \"12345.67\")\n        self.assertEqual(ac.parse_amount(\"500 ₽\"), \"500.00\")\n        self.assertEqual(ac.parse_amount(\"1.5E+3\"), \"1500.00\")\n\n    def test_ambiguous_three_decimals_warning(self):\n        amt1, warn1 = ac.parse_amount_detailed(\"1,234\")\n        self.assertEqual(amt1, \"1.23\")\n        self.assertIn(\"неоднозначный\", warn1)\n\n        amt2, warn2 = ac.parse_amount_detailed(\"1.234\")\n        self.assertEqual(amt2, \"1.23\")\n        self.assertIn(\"неоднозначный\", warn2)\n\n        amt3, warn3 = ac.parse_amount_detailed(\"0.125\")\n        self.assertEqual(amt3, \"0.13\")\n        self.assertEqual(warn3, \"\")\n\n    def test_plausibility_thresholds_and_invalid(self):\n        amt_large, warn_large = ac.parse_amount_detailed(\"15 000 000\")\n        self.assertEqual(amt_large, \"15000000.00\")\n        self.assertIn(\"10 000 000\", warn_large)\n\n        amt_huge, warn_huge = ac.parse_amount_detailed(\"999 999 999 999 999\")\n        self.assertIsNone(amt_huge)\n        self.assertIn(\"порог правдоподобия\", warn_huge)\n\n        self.assertIsNone(ac.parse_amount(\"-100.50\"))\n        self.assertIsNone(ac.parse_amount(\"—100\"))\n        self.assertIsNone(ac.parse_amount(\"да\"))\n        self.assertIsNone(ac.parse_amount(\"\"))\n        self.assertIsNone(ac.parse_amount(None))\n\n\nclass TestFioDeclension(unittest.TestCase):\n    \"\"\"Тесты склонения ФИО должника в родительный и дательный падежи.\"\"\"\n\n    def test_standard_male_and_female(self):\n        self.assertEqual(ac.decline_fio(\"Иванов Иван Иванович\", \"gent\"),\n                         \"Иванова Ивана Ивановича\")\n        self.assertEqual(ac.decline_fio(\"Иванов Иван Иванович\", \"datv\"),\n                         \"Иванову Ивану Ивановичу\")\n\n        self.assertEqual(ac.decline_fio(\"Петрова Анна Сергеевна\", \"gent\"),\n                         \"Петровой Анны Сергеевны\")\n        self.assertEqual(ac.decline_fio(\"Петрова Анна Сергеевна\", \"datv\"),\n                         \"Петровой Анне Сергеевне\")\n\n    def test_special_names_and_surnames(self):\n        self.assertEqual(ac.decline_fio(\"Смирнова Мария Ильинична\", \"gent\"),\n                         \"Смирновой Марии Ильиничны\")\n        self.assertEqual(ac.decline_fio(\"Смирнова Мария Ильинична\", \"datv\"),\n                         \"Смирновой Марии Ильиничне\")\n\n        self.assertEqual(ac.decline_fio(\"Ковалевский Дмитрий Олегович\", \"gent\"),\n                         \"Ковалевского Дмитрия Олеговича\")\n        self.assertEqual(ac.decline_fio(\"Ковалевская Софья Васильевна\", \"gent\"),\n                         \"Ковалевской Софьи Васильевны\")\n\n        self.assertEqual(ac.decline_fio(\"Шевченко Тарас Григорьевич\", \"gent\"),\n                         \"Шевченко Тараса Григорьевича\")\n        self.assertEqual(ac.decline_fio(\"Черных Ольга Викторовна\", \"gent\"),\n                         \"Черных Ольги Викторовны\")\n        self.assertEqual(ac.decline_fio(\"Мельник Елена Петровна\", \"gent\"),\n                         \"Мельник Елены Петровны\")\n        self.assertEqual(ac.decline_fio(\"Мельник Андрей Петрович\", \"gent\"),\n                         \"Мельника Андрея Петровича\")\n\n        self.assertEqual(ac.decline_fio(\"Сидоров Никита Павлович\", \"gent\"),\n                         \"Сидорова Никиты Павловича\")\n        self.assertEqual(ac.decline_fio(\"Кузьмин Илья Фёдорович\", \"datv\"),\n                         \"Кузьмину Илье Фёдоровичу\")\n        self.assertEqual(ac.decline_fio(\"Орлов Павел Львович\", \"gent\"),\n                         \"Орлова Павла Львовича\")\n\n        self.assertEqual(ac.decline_fio(\"Салтыков-Щедрин Михаил Евграфович\", \"gent\"),\n                         \"Салтыкова-Щедрина Михаила Евграфовича\")\n        self.assertEqual(ac.decline_fio(\"Иванов И.И.\", \"gent\"),\n                         \"Иванова И.И.\")\n        self.assertEqual(ac.decline_fio(\"Борец Илья Петрович\", \"gent\"),\n                         \"Борца Ильи Петровича\")\n\n    def test_acting_judge_preamble(self):\n        st = ac.DocSettings(\n            section=\"Димитровский судебный участок г. Сыктывкара\",\n            judge=\"Петров П.П.\",\n            is_acting=True,\n            acting_section=\"Куратовский судебный участок г. Сыктывкара\",\n        )\n        self.assertEqual(\n            st.judge_intro_clause,\n            \"Мировой судья Куратовского судебного участка г. Сыктывкара Республики Коми Петров П.П., \"\n            \"исполняющий обязанности мирового судьи Димитровского судебного участка г. Сыктывкара Республики Коми\",\n        )\n\n\nclass TestRegistryAndWordIntegration(unittest.TestCase):\n    \"\"\"Интеграционные тесты XML-конвертации, скрининга и генерации документов Word.\"\"\"\n\n    def test_xml_american_amount_and_soft_paid_duty(self):\n        with tempfile.TemporaryDirectory() as tmp:\n            xlsx_path = os.path.join(tmp, \"reg.xlsx\")\n            headers = [\n                \"Взыскатель\", \"Должник_ФИО\", \"Дата_Рождения\", \"Место_Рождения\",\n                \"Адрес_Регистрации\", \"Сумма_Долга\", \"СНИЛС\", \"Оплачено_Пошлины\"\n            ]\n            rows = [\n                [\"ООО «ЖКХ»\", \"Иванов Иван Иванович\", \"01.01.1980\", \"г. Сыктывкар\",\n                 \"г. Сыктывкар, ул. Ленина, д. 1\", \"1,234.56\", \"112-233-445 95\", \"да\"],\n                [\"ООО «ЖКХ»\", \"Сидоров Пётр Петрович\", \"02.02.1985\", \"г. Ухта\",\n                 \"г. Ухта, ул. Мира, д. 2\", \"999 999 999 999 999\", \"112-233-445 95\", \"500\"],\n            ]\n            _build_test_xlsx(xlsx_path, headers, rows)\n\n            res = ac.process_registry(xlsx_path, court_code=\"11MS001\", output_dir=tmp, journal=False)\n            self.assertEqual(res.success_count, 1)\n            self.assertEqual(len(res.rejected), 1)\n            self.assertIn(\"порог правдоподобия\", res.rejected[0][\"Причина\"])\n\n            tree = ET.parse(res.xml_path)\n            debt_text = tree.find(\".//PrincipalDebt\").text\n            duty_text = tree.find(\".//StateDuty\").text\n            self.assertEqual(debt_text, \"1234.56\")\n            self.assertEqual(duty_text, \"0.00\")\n\n            self.assertTrue(os.path.isfile(res.warnings_log_path))\n            with open(res.warnings_log_path, \"r\", encoding=\"utf-8-sig\") as fh:\n                warn_content = fh.read()\n            self.assertIn(\"Оплачено_Пошлины\", warn_content)\n\n    def test_word_package_declension_and_screening_filter(self):\n        with tempfile.TemporaryDirectory() as tmp:\n            xlsx_path = os.path.join(tmp, \"orders.xlsx\")\n            headers = [\n                \"Взыскатель\", \"Должник_ФИО\", \"Дата_Рождения\", \"Место_Рождения\",\n                \"Адрес_Регистрации\", \"Сумма_Долга\", \"СНИЛС\",\n                \"Категория_Требования\", \"Документы_Приложены\", \"Заявление_Подписано\",\n                \"Оплачено_Пошлины\", \"Признаки_Спора\"\n            ]\n            rows = [\n                [\"ТСЖ «Север»\", \"Иванов Иван Иванович\", \"10.05.1982\", \"г. Сыктывкар\",\n                 \"г. Сыктывкар, ул. Кирова, д. 10\", \"15000,00\", \"112-233-445 95\",\n                 \"оплата жилого помещения, коммунальных услуг, услуг связи\", \"да\", \"да\", \"2000\", \"нет\"],\n                [\"ООО «Кредит»\", \"Петров Пётр Петрович\", \"12.06.1975\", \"г. Воркута\",\n                 \"г. Воркута, ул. Горняков, д. 5\", \"600000,00\", \"112-233-445 95\",\n                 \"сделка в простой письменной форме\", \"да\", \"да\", \"8750\", \"нет\"],\n                [\"ООО «Связь»\", \"Сидорова Анна Ивановна\", \"15.08.1990\", \"г. Инта\",\n                 \"г. Инта, ул. Полярная, д. 3\", \"5000,00\", \"112-233-445 95\",\n                 \"оплата жилого помещения, коммунальных услуг, услуг связи\", \"нет\", \"да\", \"2000\", \"нет\"],\n                [\"УК «Уют»\", \"Кузнецова Мария Сергеевна\", \"20.11.1988\", \"г. Печора\",\n                 \"г. Печора, ул. Речная, д. 7\", \"22000,00\", \"112-233-445 95\",\n                 \"оплата жилого помещения, коммунальных услуг, услуг связи\", \"да\", \"да\", \"2000\", \"да\"],\n            ]\n            _build_test_xlsx(xlsx_path, headers, rows)\n\n            st = ac.DocSettings(section=\"Димитровский судебный участок г. Сыктывкара\", judge=\"Смирнова Е.В.\")\n            pkg = ac.generate_document_package(xlsx_path, st, output_dir=tmp, journal=False)\n\n            self.assertEqual(pkg.debtors, 2)\n            self.assertEqual(len(pkg.excluded_orders), 2)\n            self.assertEqual(len(pkg.order_warnings), 1)\n\n            orders_docx = os.path.join(pkg.folder, \"01_Проекты_судебных_приказов.docx\")\n            orders_text = _read_docx_text(orders_docx)\n\n            self.assertIn(\"Взыскать с Иванова Ивана Ивановича\", orders_text)\n            self.assertIn(\"Взыскать с Кузнецовой Марии Сергеевны\", orders_text)\n            self.assertNotIn(\"Петрова Петра Петровича\", orders_text)\n            self.assertNotIn(\"Сидоровой Анны Ивановны\", orders_text)\n            self.assertIn(\"ВНИМАНИЕ СУДЬЕ — ТРЕБУЕТСЯ ПРОВЕРКА ПО СТ. 125 ГПК РФ\", orders_text)\n\n            env_docx = os.path.join(pkg.folder, \"04_Конверты_ярлыки.docx\")\n            env_text = _read_docx_text(env_docx)\n            self.assertIn(\"Кому: Иванову Ивану Ивановичу\", env_text)\n            self.assertIn(\"Кому: Кузнецовой Марии Сергеевне\", env_text)\n\n            readme_path = os.path.join(pkg.folder, \"00_ПАМЯТКА.txt\")\n            with open(readme_path, \"r\", encoding=\"utf-8-sig\") as fh:\n                readme = fh.read()\n            self.assertIn(\"ИСКЛЮЧЕНЫ ИЗ ПРОЕКТОВ ПРИКАЗОВ\", readme)\n            self.assertIn(\"Петров Пётр Петрович\", readme)\n            self.assertIn(\"Сидорова Анна Ивановна\", readme)\n\n\nclass TestFeesAndMonotonicRegistry(unittest.TestCase):\n    \"\"\"Тесты шкалы госпошлины > 1 млн руб. и монотонного счётчика ID заявок.\"\"\"\n\n    def test_state_duty_above_1m(self):\n        self.assertEqual(ac.state_duty_order(\"1500000\"), \"15000.00\")\n        self.assertEqual(ac.state_duty_order(\"1000000\"), \"12500.00\")\n        self.assertEqual(ac.state_duty_order(\"500000\"), \"7500.00\")\n\n    def test_monotonic_claim_ids_after_delete(self):\n        with tempfile.TemporaryDirectory() as tmp:\n            reg_path = os.path.join(tmp, \"claims.csv\")\n            ids1 = ac.append_claim_rows([\n                {\"Должник\": \"Первый\"},\n                {\"Должник\": \"Второй\"},\n                {\"Должник\": \"Третий\"},\n            ], path=reg_path)\n            self.assertEqual(ids1, [\"З-000001\", \"З-000002\", \"З-000003\"])\n\n            removed = ac.remove_claim_rows([\"З-000003\"], path=reg_path)\n            self.assertEqual(removed, 1)\n\n            ids2 = ac.append_claim_rows([{\"Должник\": \"Четвёртый\"}], path=reg_path)\n            self.assertEqual(ids2, [\"З-000004\"])\n\n    def test_screening_soft_handling_for_yes_in_paid_duty(self):\n        with tempfile.TemporaryDirectory() as tmp:\n            xlsx_path = os.path.join(tmp, \"screen_yes.xlsx\")\n            headers = [\n                \"Взыскатель\", \"Должник_ФИО\", \"Дата_Рождения\", \"Место_Рождения\",\n                \"Адрес_Регистрации\", \"Сумма_Долга\", \"СНИЛС\",\n                \"Категория_Требования\", \"Документы_Приложены\", \"Заявление_Подписано\",\n                \"Оплачено_Пошлины\"\n            ]\n            rows = [\n                [\"ООО «УК»\", \"Иванов Иван Иванович\", \"01.01.1980\", \"г. Сыктывкар\",\n                 \"г. Сыктывкар, ул. Мира, д. 1\", \"10000\", \"112-233-445 95\",\n                 \"оплата жилого помещения, коммунальных услуг, услуг связи\", \"да\", \"да\", \"да\"],\n            ]\n            _build_test_xlsx(xlsx_path, headers, rows)\n            st = ac.DocSettings(section=\"Димитровский судебный участок г. Сыктывкара\")\n            scr = ac.generate_screening_package(xlsx_path, st, output_dir=tmp, journal=False)\n            self.assertEqual(scr.return_count, 0)\n            self.assertEqual(scr.manual_count, 1)\n            manual_texts = [f.text for f in scr.entries[0].findings if f.kind == \"manual\"]\n            self.assertTrue(any(\"укажите сумму в рублях\" in t for t in manual_texts), manual_texts)\n\n\nif __name__ == \"__main__\":\n    unittest.main(verbosity=2)\n",
  "test_amirs_regression.py": "# -*- coding: utf-8 -*-\n\"\"\"Регрессионные тесты по итогам аудита (версии 3.8.1 и 3.8.2).\n\nЗапуск: python -m unittest test_amirs_regression -v (или: pytest test_amirs_regression.py)\nКаждый тест соответствует дефекту из перечня аудита (номер указан в имени класса/теста).\n\"\"\"\nimport contextlib\nimport io\nimport os\nimport shutil\nimport tempfile\nimport threading\nimport time\nimport unittest\nimport zipfile\n\nimport amirs_converter as ac\nfrom test_amirs_converter import _build_test_xlsx, _read_docx_text\n\n_TMP_ROOT = None\n\n\ndef setUpModule():\n    \"\"\"Изолируем файлы программы (журналы, настройки, шкала пошлины) во временной папке.\"\"\"\n    global _TMP_ROOT\n    _TMP_ROOT = tempfile.mkdtemp(prefix=\"amirs_regr_\")\n    ac._app_data_dir = lambda: _TMP_ROOT  # noqa: E731\n    if hasattr(ac, \"_FEES_CACHE\"):\n        ac._FEES_CACHE.clear()\n\n\ndef tearDownModule():\n    shutil.rmtree(_TMP_ROOT, ignore_errors=True)\n\n\ndef _tmpdir(testcase):\n    d = tempfile.mkdtemp(prefix=\"amirs_t_\")\n    testcase.addCleanup(shutil.rmtree, d, True)\n    return d\n\n\ndef _w(dirpath, name, data):\n    p = os.path.join(dirpath, name)\n    mode = \"wb\" if isinstance(data, bytes) else \"w\"\n    with open(p, mode, **({} if mode == \"wb\" else {\"encoding\": \"utf-8\"})) as fh:\n        fh.write(data)\n    return p\n\n\nHEADERS = ac.REQUIRED_COLUMNS + ac.OPTIONAL_COLUMNS + ac.SCREENING_COLUMNS\nBASE_ROW = {\n    \"Взыскатель\": \"ООО Тепло\", \"Должник_ФИО\": \"Иванов Иван Иванович\", \"Дата_Рождения\": \"01.02.1980\",\n    \"Место_Рождения\": \"г. Ухта\", \"Адрес_Регистрации\": \"г. Ухта, ул. Мира, 1\", \"Сумма_Долга\": \"12345.67\",\n    \"СНИЛС\": \"112-233-445 95\", \"Категория_Требования\": \"оплата жилого помещения, коммунальных услуг, услуг связи\",\n    \"Дата_Поступления\": \"10.11.2026\", \"Страна_Должника\": \"Россия\", \"Документы_Приложены\": \"да\",\n    \"Заявление_Подписано\": \"да\", \"Доверенность_Есть\": \"да\", \"Признаки_Спора\": \"нет\",\n    \"Оплачено_Пошлины\": \"2000\",\n}\n\n\ndef _row(**kw):\n    d = dict(BASE_ROW)\n    d.update(kw)\n    return [d.get(h, \"\") for h in HEADERS]\n\n\n# ============================== P0: целостность данных ==============================\nclass P0_DataIntegrity(unittest.TestCase):\n    GOOD = dict(Взыскатель=\"ООО Тепло\", Должник=\"Иванов Иван Иванович\", Дата_рождения=\"01.02.1980\",\n                Место_рождения=\"Ухта\", Адрес=\"Ухта, Мира 1\", СНИЛС=\"112-233-445 95\",\n                Сумма_долга=\"1000\", Пени=\"0\")\n\n    def _claim(self, **kw):\n        d = dict(self.GOOD, Вердикт=ac.V_OK)\n        d.update(kw)\n        return d\n\n    def test_d1_parallel_appends_not_lost(self):\n        \"\"\"№1: 8 потоков × 10 записей — ни одна не теряется, ID уникальны.\"\"\"\n        path = os.path.join(_tmpdir(self), \"claims.csv\")\n\n        def worker(i):\n            for _ in range(10):\n                ac.append_claim_rows([self._claim(Должник=f\"Т{i}\")], path)\n\n        ts = [threading.Thread(target=worker, args=(i,)) for i in range(8)]\n        [t.start() for t in ts]\n        [t.join() for t in ts]\n        rows = ac.read_claims_registry(path)\n        self.assertEqual(len(rows), 80)\n        self.assertEqual(len({r[\"ID\"] for r in rows}), 80)\n\n    def test_d2_purge_does_not_touch_unsent_namesake(self):\n        \"\"\"№2: после отправки одной заявки данные неотправленного однофамильца целы.\"\"\"\n        d = _tmpdir(self)\n        path = os.path.join(d, \"claims.csv\")\n        ids = ac.append_claim_rows([\n            self._claim(),\n            self._claim(Дата_рождения=\"05.05.1965\", Адрес=\"\", Сумма_долга=\"7777\"),  # неполная: не уйдёт\n        ], path)\n        res = ac.send_claims_to_amirs(\"11MS001\", os.path.join(d, \"pk.xml\"), path=path)\n        self.assertEqual(res.sent_ids, [ids[0]])\n        rows = {r[\"ID\"]: r for r in ac.read_claims_registry(path)}\n        self.assertEqual(rows[ids[1]][\"Должник\"], \"Иванов Иван Иванович\")\n        self.assertEqual(rows[ids[1]][\"Дата_рождения\"], \"05.05.1965\")\n        self.assertNotIn(\"удалены\", rows[ids[1]][\"Должник\"].lower())\n\n    def test_d3_negative_amount_rejected(self):\n        \"\"\"№3: отрицательная сумма не превращается в положительную.\"\"\"\n        self.assertIsNone(ac.parse_amount(\"-5\"))\n        self.assertIsNone(ac.parse_amount(\"-100\"))\n        d = _tmpdir(self)\n        p = _build_test_xlsx(os.path.join(d, \"r.xlsx\"), HEADERS,\n                             [_row(), _row(Должник_ФИО=\"Минусов Михаил Михайлович\", Сумма_Долга=\"-100\")])\n        r = ac.process_registry(p, output_dir=d)\n        self.assertEqual(r.success_count, 1)\n        self.assertEqual(len(r.rejected), 1)\n        only_neg = _build_test_xlsx(os.path.join(d, \"n.xlsx\"), HEADERS, [_row(Сумма_Долга=\"-100\")])\n        with self.assertRaises(ac.ConversionError):  # все строки забракованы — пакета нет\n            ac.process_registry(only_neg, output_dir=d)\n\n    def test_d4_amount_formats(self):\n        \"\"\"№4: форматы сумм (в т.ч. американский) разбираются верно, мусор отклоняется.\"\"\"\n        cases = {\"1 234,56\": \"1234.56\", \"1,234.56\": \"1234.56\", \"12,345.67\": \"12345.67\",\n                 \"1.234,56\": \"1234.56\", \"1,234,567.89\": \"1234567.89\", \"1 234,56 руб.\": \"1234.56\",\n                 \"12 345,67 ₽\": \"12345.67\", \"1234.5\": \"1234.50\"}\n        for raw, want in cases.items():\n            self.assertEqual(str(ac.parse_amount(raw)), want, raw)\n        for bad in (\"abc\", \"\", \"1..2\", \"1,,2\", \"5-\"):\n            self.assertIsNone(ac.parse_amount(bad), bad)\n\n    def test_d4_claim_id_not_reused(self):\n        path = os.path.join(_tmpdir(self), \"claims.csv\")\n        ids = ac.append_claim_rows([self._claim(), self._claim(Должник=\"Петров Пётр\")], path)\n        ac.remove_claim_rows([ids[-1]], path)\n        new_id = ac.append_claim_rows([self._claim(Должник=\"Сидоров Сидор\")], path)[0]\n        self.assertNotIn(new_id, ids)\n\n    def test_d4_fee_scale_above_one_million(self):\n        ac._FEES_CACHE.clear()\n        self.assertEqual(ac.state_duty_order(\"500000\"), \"7500.00\")\n        self.assertEqual(ac.state_duty_order(\"1000000\"), \"12500.00\")\n        self.assertEqual(ac.state_duty_order(\"1500000\"), \"15000.00\")\n        self.assertEqual(ac.state_duty_order(\"3000000\"), \"22500.00\")\n\n    def test_d4_amount_plausibility_cap(self):\n        d = _tmpdir(self)\n        p = _build_test_xlsx(os.path.join(d, \"r.xlsx\"), HEADERS,\n                             [_row(), _row(Должник_ФИО=\"Огромов Олег Олегович\", Сумма_Долга=\"999999999999999\")])\n        r = ac.process_registry(p, output_dir=d)\n        self.assertEqual(r.success_count, 1)\n        self.assertEqual(len(r.rejected), 1)\n\n\n# ============================== P1: проекты приказов ==============================\nclass P1_OrderPackage(unittest.TestCase):\n    def _build(self):\n        d = _tmpdir(self)\n        rows = [\n            _row(Должник_ФИО=\"Иванов Иван Иванович\"),  # норма\n            _row(Должник_ФИО=\"Большов Борис Борисович\", Сумма_Долга=\"600000\", Оплачено_Пошлины=\"9500\"),\n            _row(Должник_ФИО=\"Неподписанов Николай Николаевич\", Заявление_Подписано=\"нет\"),\n            _row(Должник_ФИО=\"Недоплатов Пётр Петрович\", Оплачено_Пошлины=\"500\"),  # пошлина уплачена не полностью\n            _row(Должник_ФИО=\"Неуказанов Николай Николаевич\", Оплачено_Пошлины=\"\"),  # сумма не указана, льготы нет\n            _row(Должник_ФИО=\"Алиментов Алексей Алексеевич\",\n                 Категория_Требования=\"алименты на несовершеннолетних детей\", Оплачено_Пошлины=\"\",\n                 Льгота_Пошлина=\"да\"),  # освобождён\n        ]\n        p = _build_test_xlsx(os.path.join(d, \"r.xlsx\"), HEADERS, rows)\n        st = ac.DocSettings()\n        st.section = \"Димитровский судебный участок г. Сыктывкара\"\n        st.judge = \"Тестов Т.Т.\"\n        res = ac.generate_document_package(p, st, output_dir=d)\n        order_path = [f for f in res.files if \"01_\" in os.path.basename(f)][0]\n        return res, _read_docx_text(order_path)\n\n    def test_d5_refused_and_returned_rows_not_in_orders(self):\n        res, text = self._build()\n        self.assertIn(\"Иванова Ивана Ивановича\", text)  # склонение\n        self.assertIn(\"Алиментова Алексея Алексеевича\", text)\n        for name in (\"Большова\", \"Неподписанова\", \"Недоплатова\"):\n            self.assertNotIn(name, text)\n        self.assertEqual(res.debtors, 3)  # норма, «сумма не указана», освобождённый\n        self.assertEqual(len(res.excluded_orders), 3)  # 600 тыс., без подписи, недоплата\n        self.assertIn(\"Неуказанова Николая Николаевича\", text)\n        self.assertIn(\"ТРЕБУЕТСЯ ПРОВЕРКА ПО СТ. 125\", text)  # неуказанная пошлина — пометка судье\n\n    def test_d6_budget_duty_only_for_exempt_claimant(self):\n        \"\"\"№6: «в доход бюджета» — только у освобождённого заявителя, не у неплательщика.\"\"\"\n        _res, text = self._build()\n        self.assertEqual(text.count(\"в доход местного бюджета\"), 1)\n        pos = text.index(\"в доход местного бюджета\")\n        self.assertIn(\"Алиментова\", text[max(0, pos - 200):pos])\n        self.assertNotIn(\"доход местного бюджета государственную пошлину, от уплаты которой взыскатель освобождён, \"\n                         \"в размере\", text[:text.index(\"Алиментова Алексея Алексеевича,\")])\n\n\n# ============================== P1: ZIP и вложения ==============================\nclass P1_ZipSafety(unittest.TestCase):\n    TXT = \"Расчёт задолженности по лицевому счёту 201601234567 за период 01.01.2025 по 31.03.2025\"\n\n    def test_d8_member_over_limit_skipped_not_extracted(self):\n        d = _tmpdir(self)\n        p = os.path.join(d, \"bomb.zip\")\n        with zipfile.ZipFile(p, \"w\", zipfile.ZIP_DEFLATED) as z:\n            z.writestr(\"big.txt\", \"0\" * (ac._ZIP_MAX_MEMBER_BYTES + 1024 * 1024))\n            z.writestr(\"ok.txt\", self.TXT)\n        t0 = time.time()\n        text, note, ch = ac.extract_document_text(p)\n        self.assertLess(time.time() - t0, 10)\n        self.assertEqual(ch, \"text\")\n        self.assertIn(\"расчёт\", text.lower())\n        self.assertIn(\"слишком велик\", note)\n        self.assertLess(len(text), 10_000)\n\n    def test_d8_nested_archive_not_opened(self):\n        d = _tmpdir(self)\n        inner = os.path.join(d, \"inner.zip\")\n        with zipfile.ZipFile(inner, \"w\") as z:\n            z.writestr(\"a.txt\", self.TXT)\n        outer = os.path.join(d, \"outer.zip\")\n        with zipfile.ZipFile(outer, \"w\") as z:\n            z.write(inner, \"inner.zip\")\n        text, note, ch = ac.extract_document_text(outer)\n        self.assertEqual(text, \"\")\n        self.assertIn(\"вложенный архив\", note)\n\n    def test_d8_member_count_capped(self):\n        d = _tmpdir(self)\n        p = os.path.join(d, \"many.zip\")\n        with zipfile.ZipFile(p, \"w\") as z:\n            for i in range(ac._ZIP_MAX_MEMBERS + 15):\n                z.writestr(f\"f{i:02d}.txt\", f\"Договор № {i} \" + self.TXT)\n        text, note, ch = ac.extract_document_text(p)\n        self.assertEqual(text.count(\"Договор №\"), ac._ZIP_MAX_MEMBERS)\n        self.assertIn(\"первые\", note)\n\n    def test_d8_path_traversal_names_never_written_outside(self):\n        d = _tmpdir(self)\n        p = os.path.join(d, \"slip.zip\")\n        marker = os.path.join(os.path.dirname(d), \"evil_marker_amirs.txt\")\n        with zipfile.ZipFile(p, \"w\") as z:\n            z.writestr(\"../evil_marker_amirs.txt\", \"Договор расчёт\")\n            z.writestr(\"/abs_evil_marker_amirs.txt\", \"Договор\")\n        text, _note, _ch = ac.extract_document_text(p)\n        self.assertFalse(os.path.exists(marker))\n        self.assertFalse(os.path.exists(\"/abs_evil_marker_amirs.txt\"))\n        self.assertIn(\"договор\", text.lower())\n\n    def test_corrupt_zip_is_fail_not_crash(self):\n        d = _tmpdir(self)\n        p = _w(d, \"bad.zip\", b\"PK\\x03\\x04garbage\")\n        self.assertEqual(ac.extract_document_text(p)[2], \"fail\")\n\n\n# ============================== P2: классификация и файлы подписи ==============================\nclass P2_Classification(unittest.TestCase):\n    def test_d10_signature_files_are_not_claims(self):\n        d = _tmpdir(self)\n        junk = _w(d, \"junk.sig\", os.urandom(300)[1:])  # не ASN.1\n        empty = _w(d, \"empty.cer\", b\"\")\n        der = _w(d, \"real.sig\", b\"\\x30\\x82\\x01\\x00\" + os.urandom(300))\n        pem = _w(d, \"cert.crt\", \"-----BEGIN CERTIFICATE-----\\nMIIB\\n-----END CERTIFICATE-----\\n\")\n        for p in (junk, empty):\n            info = ac.analyze_attachment_file(p)\n            self.assertEqual(info.status, ac.DOC_STATUS_FAIL, p)\n        for p in (der, pem):\n            info = ac.analyze_attachment_file(p)\n            self.assertEqual(info.kind, ac.DOC_KIND_EDS)\n            self.assertNotEqual(info.kind, ac.DOC_KIND_ZAYAVLENIE)\n        res = ac.check_claim_documents(d, [[ac.DOC_KIND_RASCHET]])\n        self.assertNotIn(ac.DOC_KIND_ZAYAVLENIE, res.found_kinds)\n        self.assertIn(\"само заявление среди файлов не распознано\", res.note)\n\n    def test_d11_egrn_only_by_explicit_wording(self):\n        k = lambda t: ac.classify_document_text(t)[0]  # noqa: E731\n        self.assertEqual(k(\"Выписка из ЕГРН об объекте недвижимости. Кадастровый номер 11:05:0101001:1\"),\n                         ac.DOC_KIND_EGRN)\n        self.assertEqual(k(\"Выписка из Единого государственного реестра недвижимости о правах\"),\n                         ac.DOC_KIND_EGRN)\n        self.assertNotEqual(k(\"Квитанция за ЖКУ. Кадастровый номер 11:05:0101001:1\"), ac.DOC_KIND_EGRN)\n        self.assertNotEqual(k(\"Карточка лицевого счёта № 123\"), ac.DOC_KIND_EGRN)\n        self.assertNotIn(ac.DOC_KIND_EGRN, ac.classify_all_document_kinds(\"карточка лицевого счёта, кадастровый номер\"))\n\n    def test_egrn_alternative_to_contract_in_profile(self):\n        d = _tmpdir(self)\n        _w(d, \"1_egrn.txt\", \"Выписка из ЕГРН об объекте недвижимости\")\n        _w(d, \"2_raschet.txt\", \"Расчёт задолженности по оплате за период\")\n        _w(d, \"3_pochta.txt\", \"Список почтовых отправлений. Уведомление о вручении\")\n        groups = ac.DEFAULT_DOC_PROFILES[\"оплата жилого помещения, коммунальных услуг, услуг связи\"]\n        res = ac.check_claim_documents(d, groups)\n        self.assertEqual(res.missing, [])\n\n    def test_rpo_pattern_matches_cyrillic(self):\n        self.assertEqual(ac.classify_document_text(\"Отправление РПО 16700012345678 принято\")[0], ac.DOC_KIND_POST)\n\n    def test_single_image_ocr_no_name_error(self):\n        text, note = ac._run_paddle_ocr_single(\"nonexistent.jpg\", \"\")\n        self.assertEqual(text, \"\")\n        self.assertIn(\"PaddleOCR\", note)\n\n\n# ============================== Новые читалки вложений ==============================\nclass Readers(unittest.TestCase):\n    CYR = \"Расчёт задолженности по лицевому счёту 201601234567 за период с 01.01.2025 по 31.03.2025 составляет 12 345,67 руб.\"\n\n    def _ex(self, name, data):\n        d = _tmpdir(self)\n        return ac.extract_document_text(_w(d, name, data))\n\n    def test_text_formats(self):\n        self.assertIn(\"расчёт\", self._ex(\"a.txt\", self.CYR)[0].lower())\n        self.assertIn(\"расчёт\", self._ex(\"b.txt\", self.CYR.encode(\"cp1251\"))[0].lower())\n        t = self._ex(\"a.html\", \"<html><script>var x=1;</script><body><p>\" + self.CYR + \"</p></body></html>\")[0]\n        self.assertIn(\"расчёт\", t.lower())\n        self.assertNotIn(\"var x\", t)\n        self.assertIn(\"расчёт\", self._ex(\"a.xml\", \"<r><a>\" + self.CYR + \"</a></r>\")[0].lower())\n        self.assertEqual(self._ex(\"e.txt\", \"\")[2], \"scan\")\n\n    def test_csv_xlsx_ods(self):\n        self.assertIn(\"1000,50\", self._ex(\"a.csv\", \"Период;Начислено\\n01.2025;1000,50\\n\")[0])\n        d = _tmpdir(self)\n        p = _build_test_xlsx(os.path.join(d, \"a.xlsx\"), [\"Период\", \"Начислено\"], [[\"01.2025\", \"1000.5\"]])\n        self.assertIn(\"1000.5\", ac.extract_document_text(p)[0])\n        ods = os.path.join(d, \"a.ods\")\n        with zipfile.ZipFile(ods, \"w\") as z:\n            z.writestr(\"content.xml\", '<?xml version=\"1.0\"?><o xmlns:text=\"t\"><text:p>Начислено 1000</text:p></o>')\n        self.assertIn(\"Начислено 1000\", ac.extract_document_text(ods)[0])\n\n    def test_rtf_both_encodings(self):\n        body = self.CYR.encode(\"cp1251\")\n        rtf = b\"{\\\\rtf1\\\\ansi\\\\ansicpg1251 \" + b\"\".join(\n            b\"\\\\'%02x\" % c if c > 127 else bytes([c]) for c in body) + b\"}\"\n        self.assertIn(\"задолженности\", self._ex(\"a.rtf\", rtf)[0])\n        u = \"{\\\\rtf1\\\\ansi \" + \"\".join(\n            \"\\\\u%d?\" % (ord(c) if ord(c) < 32768 else ord(c) - 65536) if ord(c) > 127 else c for c in self.CYR) + \"}\"\n        self.assertIn(\"задолженности\", self._ex(\"u.rtf\", u.encode(\"ascii\"))[0])\n\n    def test_d13_doc_binary_text_vs_garbage(self):\n        good = os.urandom(300) + (\"Договор управления многоквартирным домом. \" + self.CYR).encode(\"utf-16-le\") + os.urandom(300)\n        text, _n, ch = self._ex(\"a.doc\", good)\n        self.assertEqual(ch, \"text\")\n        self.assertIn(\"договор\", text.lower())\n        for _ in range(5):  # случайные байты — не «текст»\n            self.assertEqual(self._ex(\"r.doc\", os.urandom(6000))[2], \"scan\")\n\n    def test_unsupported_and_hostile(self):\n        self.assertEqual(self._ex(\"a.xyz\", b\"abc\")[2], \"fail\")\n        t0 = time.time()\n        self._ex(\"big.rtf\", b\"{\\\\rtf1 \" + b\"{\" * 2_000_000 + b\"}\")\n        self.assertLess(time.time() - t0, 20)\n\n\n# ============================== Экспресс-разбор заявления ==============================\nclass ClaimTextParser(unittest.TestCase):\n    TXT = (\"Заявление о вынесении судебного приказа. Взыскатель: ООО «Тепло-Сервис» Адрес: г. Ухта, ул. Мира, 1 ИНН 1101234567\\n\"\n           \"Должник: Иванов Иван Иванович\\nДата рождения: 01.02.1980 Место рождения: г. Ухта \"\n           \"Адрес регистрации: г. Ухта, ул. Мира, д. 5, кв. 7 СНИЛС 112-233-445 95\\n\"\n           \"Лицевой счёт № 201601234567. Прошу взыскать задолженность по оплате жилого помещения и коммунальных услуг \"\n           \"за период с 01.01.2025 по 31.03.2025 в размере 12 345,67 руб. основного долга, пени в размере 345,10 руб., \"\n           \"госпошлину в размере 2 000 руб.\")\n\n    def test_d12_fields(self):\n        f = ac.parse_claim_text_fields(self.TXT)\n        self.assertEqual(f[\"ФИО должника\"], \"Иванов Иван Иванович\")  # без «\\nДата»\n        self.assertIn(\"д. 5, кв. 7\", f[\"Адрес должника\"])  # адрес должника, не взыскателя\n        self.assertNotIn(\"Мира, 1\", f[\"Адрес должника\"].replace(\"д. 5\", \"\"))\n        self.assertEqual(f[\"Период задолженности\"], \"с 01.01.2025 по 31.03.2025\")\n        self.assertEqual(str(f[\"Сумма долга, руб.\"]), \"12345.67\")\n        self.assertEqual(str(f[\"Пени, руб.\"]), \"345.10\")\n        self.assertEqual(f[\"Лицевой счёт\"], \"201601234567\")\n        self.assertEqual(f[\"Дата рождения (ДД.ММ.ГГГГ)\"], \"01.02.1980\")\n\n    def test_debt_amount_either_word_order(self):\n        a = ac.parse_claim_text_fields(\"основного долга в размере 12 345,67 руб.\")\n        b = ac.parse_claim_text_fields(\"в размере 12 345,67 руб. основного долга\")\n        self.assertEqual(str(a[\"Сумма долга, руб.\"]), \"12345.67\")\n        self.assertEqual(str(b[\"Сумма долга, руб.\"]), \"12345.67\")\n\n    def test_claimant_address_not_used_when_debtor_has_none(self):\n        f = ac.parse_claim_text_fields(\"Взыскатель: ООО А Адрес: г. Ухта, ул. Мира 1\\nДолжник: Петров Пётр Петрович\")\n        self.assertNotIn(\"Адрес должника\", f)\n\n    def test_empty_and_hostile_input(self):\n        self.assertEqual(ac.parse_claim_text_fields(\"\"), {})\n        t0 = time.time()\n        ac.parse_claim_text_fields(\"Взыскатель: \" + \"а \" * 100000 + \"\\nДолжник: \" + \"Иванов \" * 50000)\n        self.assertLess(time.time() - t0, 10)\n\n    def test_cli_read_claim(self):\n        d = _tmpdir(self)\n        p = _w(d, \"claim.txt\", self.TXT)\n        buf = io.StringIO()\n        with contextlib.redirect_stdout(buf):\n            rc = ac.run_cli([\"--read-claim\", p])\n        self.assertEqual(rc, 0)\n        self.assertIn(\"ФИО должника: Иванов Иван Иванович\", buf.getvalue())\n        buf = io.StringIO()\n        with contextlib.redirect_stdout(buf):\n            self.assertEqual(ac.run_cli([\"--read-claim\", os.path.join(d, \"нет.txt\")]), 1)\n\n\nif __name__ == \"__main__\":\n    unittest.main(verbosity=2)\n"
}


def normalize_ws_regex(pattern_str: str) -> str:
    """Строит многострочное регулярное выражение с привязкой к началу строки (?m)^."""
    lines = pattern_str.splitlines()
    rx_lines = []
    for ln in lines:
        stripped = ln.strip()
        if not stripped:
            rx_lines.append(r"[ \t]*")
        else:
            tokens = re.split(r"[ \t]+", stripped)
            rx_lines.append(r"[ \t]*" + r"[ \t]+".join(re.escape(t) for t in tokens))
    return r"(?m)^" + r"\r?\n".join(rx_lines)


def patch_amirs_converter() -> None:
    filename = "amirs_converter.py"
    path = os.path.join(HERE, filename)
    if not os.path.isfile(path):
        raise FileNotFoundError(f"Не найден файл {path}")
    with open(path, "r", encoding="utf-8") as fh:
        content = fh.read()
    changed = 0
    for idx, (old, new) in enumerate(AC_REPLACEMENTS, 1):
        rx_new = normalize_ws_regex(new)
        if re.search(rx_new, content):
            continue
        rx_old = normalize_ws_regex(old)
        m = re.search(rx_old, content)
        if not m:
            raise RuntimeError(f"[{filename}] Не найден фрагмент #{idx}:\n{old[:120]}...")
        content = content[:m.start()] + new + content[m.end():]
        changed += 1
    compile(content, filename, "exec")
    with open(path, "w", encoding="utf-8", newline="\n") as fh:
        fh.write(content)
    print(f"[OK] Проверен и обновлен: {filename} (внесено изменений: {changed})")


def write_embedded_files() -> None:
    for fname, code in EMBEDDED_FILES.items():
        compile(code, fname, "exec")
        target = os.path.join(HERE, fname)
        with open(target, "w", encoding="utf-8", newline="\n") as fh:
            fh.write(code)
        print(f"[OK] Записан готовый файл v3.8.2: {fname}")


def main() -> int:
    print("=" * 65)
    print(" ОБНОВЛЕНИЕ КОМПЛЕКТА «КОНВЕРТЕР АМИРС» ДО ВЕРСИИ 3.8.2 (v4)")
    print("=" * 65)
    patch_amirs_converter()
    write_embedded_files()

    print("\nЗапуск полного набора автотестов...")
    res = subprocess.run(
        [sys.executable, "-X", "utf8", "-m", "unittest",
         "test_amirs_converter", "test_amirs_regression", "test_build_files", "-v"],
        cwd=HERE,
    )
    if res.returncode == 0:
        zip_name = os.path.join(HERE, "AMIRS_Converter_v3.8.2_Full.zip")
        pack_files = (
            "amirs_converter.py", "build_exe.py", "amirs_docs.json", "amirs_fees.json",
            "Конвертер_АМИРС.spec", "Собрать_EXE.bat",
            "test_amirs_converter.py", "test_amirs_regression.py", "test_build_files.py",
        )
        with zipfile.ZipFile(zip_name, "w", zipfile.ZIP_DEFLATED) as zf:
            for fn in pack_files:
                fp = os.path.join(HERE, fn)
                if os.path.isfile(fp):
                    zf.write(fp, arcname=fn)
        print(f"\n[ГОТОВО] Полный архив версии 3.8.2 собран: {zip_name}")
    return res.returncode


if __name__ == "__main__":
    sys.exit(main())
